    "category": "\u10EA\u10D8\u10E2\u10D0\u10E2\u10D0",
    "content": "\u201E\u10EA\u10DD\u10D3\u10DC\u10D0, \u10E0\u10DD\u10DB\u10D4\u10DA\u10E1\u10D0\u10EA \u10D0\u10E0 \u10D8\u10E7\u10D4\u10DC\u10D4\u10D1, \u10EB\u10D0\u10DA\u10D0\u10D3 \u10D5\u10D4\u10E0 \u10D8\u10E5\u10EA\u10D4\u10D5\u10D0.\u201C",
