    "content": "\u201E\u10D0\u10E0 \u10D4\u10DA\u10DD\u10D3\u10DD \u10E8\u10D4\u10E1\u10D0\u10EB\u10DA\u10D4\u10D1\u10DA\u10DD\u10D1\u10D0\u10E1. \u10E8\u10D4\u10E5\u10DB\u10D4\u10DC\u10D8 \u10D8\u10D2\u10D8.\u201C",
