    "content": "\u10D9\u10DD\u10DC\u10D3\u10D8\u10EA\u10D8\u10DD\u10DC\u10D4\u10E0\u10D8\u10E1 \u10E4\u10D8\u10DA\u10E2\u10E0\u10D8\u10E1\u10D0 \u10D3\u10D0 \u10E1\u10D0\u10D3\u10D8\u10DC\u10D0\u10E0\u10D4\u10D1\u10D8\u10E1 \u10DB\u10D3\u10D2\u10DD\u10DB\u10D0\u10E0\u10D4\u10DD\u10D1\u10D0\u10E1 \u10E7\u10E3\u10E0\u10D0\u10D3\u10E6\u10D4\u10D1\u10D0 \u10DB\u10D8\u10D0\u10E5\u10EA\u10D8\u10D4.",
