    "content": "\u201E\u10D3\u10E0\u10DD \u10E7\u10D5\u10D4\u10DA\u10D0\u10D6\u10D4 \u10EB\u10D5\u10D8\u10E0\u10E4\u10D0\u10E1\u10D8 \u10E0\u10D4\u10E1\u10E3\u10E0\u10E1\u10D8\u10D0, \u10E0\u10D0\u10D3\u10D2\u10D0\u10DC \u10E3\u10D9\u10D0\u10DC \u10D5\u10D4\u10E0 \u10D3\u10D0\u10D1\u10E0\u10E3\u10DC\u10D3\u10D4\u10D1\u10D0.\u201C \u2014 \u10D1\u10D4\u10DC\u10EF\u10D0\u10DB\u10D8\u10DC \u10E4\u10E0\u10D0\u10DC\u10D9\u10DA\u10D8\u10DC\u10D8",
