    "content": "\u201E\u10DC\u10E3 \u10E8\u10D4\u10D0\u10D3\u10D0\u10E0\u10D4\u10D1 \u10E1\u10D0\u10D9\u10E3\u10D7\u10D0\u10E0 \u10EA\u10EE\u10DD\u10D5\u10E0\u10D4\u10D1\u10D0\u10E1 \u10E1\u10EE\u10D5\u10D8\u10E1 \u10E1\u10D0\u10E3\u10D9\u10D4\u10D7\u10D4\u10E1\u10DD \u10DB\u10DD\u10DB\u10D4\u10DC\u10E2\u10D4\u10D1\u10E1.\u201C",
