    "content": "\u10E3\u10EA\u10DC\u10D0\u10E3\u10E0\u10D8 \u10EE\u10DB\u10D4\u10D1\u10D8 \u10D0\u10E0 \u10D3\u10D0\u10D0\u10D8\u10D2\u10DC\u10DD\u10E0\u10DD \u2014 \u10DB\u10EA\u10D8\u10E0\u10D4 \u10DE\u10E0\u10DD\u10D1\u10DA\u10D4\u10DB\u10D0 \u10D3\u10E0\u10DD\u10D7\u10D0 \u10D2\u10D0\u10DC\u10DB\u10D0\u10D5\u10DA\u10DD\u10D1\u10D0\u10E8\u10D8 \u10EB\u10D5\u10D8\u10E0\u10D0\u10D3\u10E6\u10D8\u10E0\u10D4\u10D1\u10E3\u10DA \u10D3\u10D0\u10D6\u10D8\u10D0\u10DC\u10D4\u10D1\u10D0\u10D3 \u10E8\u10D4\u10D8\u10EB\u10DA\u10D4\u10D1\u10D0 \u10D2\u10D0\u10D3\u10D0\u10D8\u10E5\u10EA\u10D4\u10E1.",
