    "content": "\u10E4\u10D0\u10D8\u10DA\u10D4\u10D1\u10E1 \u10E1\u10D0\u10EE\u10D4\u10DA\u10D4\u10D1\u10D8 \u10D7\u10D0\u10E0\u10D8\u10E6\u10D8\u10D7 \u10D3\u10D0 \u10D7\u10D4\u10DB\u10D8\u10D7 \u10D3\u10D0\u10D0\u10E0\u10E5\u10D5\u10D8 \u2014 \u10DE\u10DD\u10D5\u10DC\u10D0 \u10D2\u10D0\u10D2\u10D8\u10DB\u10D0\u10E0\u10E2\u10D8\u10D5\u10D3\u10D4\u10D1\u10D0.",
