    "content": "\u201E\u10D2\u10DD\u10DC\u10D4\u10D1\u10D0 \u10DE\u10D0\u10E0\u10D0\u10E8\u10E3\u10E2\u10D8\u10D5\u10D8\u10D7\u10D0\u10D0 \u2014 \u10DB\u10E3\u10E8\u10D0\u10DD\u10D1\u10E1 \u10DB\u10D0\u10E8\u10D8\u10DC, \u10E0\u10DD\u10EA\u10D0 \u10D2\u10D0\u10EE\u10E1\u10DC\u10D8\u10DA\u10D8\u10D0.\u201C \u2014 \u10E4\u10E0\u10D4\u10DC\u10D9 \u10D6\u10D0\u10DE\u10D0",
