    "content": "\u201E\u10D0\u10E0\u10D0\u10E1\u10DD\u10D3\u10D4\u10E1 \u10D0\u10E0\u10D8\u10E1 \u10D2\u10D5\u10D8\u10D0\u10DC \u10D2\u10D0\u10EE\u10D3\u10D4 \u10D8\u10E1, \u10D5\u10D8\u10DC\u10EA \u10E8\u10D4\u10D8\u10EB\u10DA\u10D4\u10D1\u10D0 \u10E7\u10DD\u10E4\u10D8\u10DA\u10D8\u10E7\u10D0\u10D5\u10D8.\u201C \u2014 \u10EF\u10DD\u10E0\u10EF \u10D4\u10DA\u10D8\u10DD\u10E2\u10D8",
