    "content": "\u201E\u10E7\u10D5\u10D4\u10DA\u10D0\u10D6\u10D4 \u10EB\u10D5\u10D8\u10E0\u10E4\u10D0\u10E1\u10D8 \u10D2\u10D0\u10D9\u10D5\u10D4\u10D7\u10D8\u10DA\u10D4\u10D1\u10D8 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10E7\u10D5\u10D4\u10DA\u10D0\u10D6\u10D4 \u10EB\u10D5\u10D8\u10E0\u10D8 \u10D2\u10D5\u10D8\u10EF\u10D3\u10D4\u10D1\u10D0.\u201C",
