    "content": "\u10E7\u10D0\u10D5\u10D0 \u10EC\u10E7\u10DA\u10D8\u10E1 \u10ED\u10D8\u10E5\u10D0\u10E1\u10D7\u10D0\u10DC \u10D4\u10E0\u10D7\u10D0\u10D3 \u10D3\u10D0\u10DA\u10D8\u10D4 \u2014 \u10D3\u10D4\u10F0\u10D8\u10D3\u10E0\u10D0\u10E2\u10D0\u10EA\u10D8\u10D0\u10E1 \u10E8\u10D4\u10D0\u10DB\u10EA\u10D8\u10E0\u10D4\u10D1.",
